INSERT INTO services (sku, name, category, duration_minutes, base_price, description, active)
SELECT sku, name, category, duration_minutes, base_price, description, true FROM imported
ON CONFLICT (sku) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, duration_minutes = EXCLUDED.duration_minutes, base_price = EXCLUDED.base_price, description = EXCLUDED.description, active = true, updated_at = now();

